// HTTP Collector test için örnek JSON response.
// Collectible şablonundaki JSON path'ler bu yapıya uyumludur.
const now = new Date().toISOString();
msg.payload = {
  timestamp: now,
  sensors: {
    temperature: 25.5 + (Math.random() * 5),
    humidity: 60 + (Math.random() * 10),
    pressure: 1013.25
  },
  storage: {
    disk: {
      usagePercent: 65 + (Math.random() * 20),
      freeGB: 100 + (Math.random() * 50)
    }
  },
  status: "healthy"
};
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
return msg;
